insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('manju-benne-dosa', 'live', 'Manju''s Benne Dosa Cart', 'Manjunath', '👨🏽‍🍳', 'Butter is not optional. Neither is a smile.', 'Basavanagudi', 12.9422, 77.5737, '🥞', 30, 'masala-dosa', array['Dosa', 'Breakfast']::text[], true, 70, '6:30 AM – 11:30 AM', '{"taste":4.9,"hygiene":4.4,"value":4.9,"vibe":4.8}'::jsonb, 412, true, null, 2014, '[{"name":"Benne Masala Dosa","price":80},{"name":"Open Butter Dosa","price":70},{"name":"Kesari Bath","price":40}]'::jsonb, 'People love the crisp, butter-soaked dosa and the coconut chutney. The main complaint is a 20-minute queue on weekends. Hygiene has improved since the new steel counter.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('akka-thatte-idli', 'live', 'Akka''s Thatte Idli', 'Savitha', '👩🏽‍🍳', 'Everyone who eats here is family. Akka is what they call me.', 'Malleshwaram', 13.0035, 77.571, '🍚', 45, 'thatte-idli', array['Idli', 'Breakfast']::text[], true, 50, '7:00 AM – 12:00 PM', '{"taste":4.7,"hygiene":4.6,"value":4.9,"vibe":4.3}'::jsonb, 268, true, null, 2018, '[{"name":"Thatte Idli (2)","price":50},{"name":"Vada","price":25},{"name":"Filter Coffee","price":20}]'::jsonb, 'Soft, plate-sized idlis praised for consistency. Very clean setup. Some say it sells out by 11 AM.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('raju-chaat-corner', 'live', 'Raju Chaat Corner', 'Raju', '👨🏾‍🍳', 'Thirty years on Food Street, and I still taste every batch.', 'VV Puram', 12.9496, 77.5736, '🥗', 140, 'masala-puri', array['Chaat', 'Evening']::text[], true, 60, '4:30 PM – 10:30 PM', '{"taste":4.8,"hygiene":3.6,"value":4.7,"vibe":4.9}'::jsonb, 530, true, null, 2011, '[{"name":"Pani Puri","price":40},{"name":"Masala Puri","price":50},{"name":"Dahi Puri","price":60}]'::jsonb, 'The masala puri is the star, often called the best on Food Street. Lively vibe. Hygiene ratings are mixed, mainly because there''s no running water at the cart.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('shivajinagar-kebab-gaadi', 'live', 'Bhai''s Kebab Gaadi', 'Imran', '🧔🏽', 'My father''s recipe, my late nights. Come hungry.', 'Shivajinagar', 12.9857, 77.6057, '🍢', 10, 'seekh-kebab', array['Kebab', 'Non-veg', 'Late night']::text[], false, 150, '6:00 PM – 1:00 AM', '{"taste":4.8,"hygiene":4,"value":4.5,"vibe":4.7}'::jsonb, 377, true, null, 2016, '[{"name":"Seekh Kebab","price":160},{"name":"Chicken Tikka","price":180},{"name":"Sulaimani Chai","price":20}]'::jsonb, 'Smoky, well-marinated kebabs and a great late-night crowd. Prices are a little higher than neighbours, but people say the portions justify it.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('kumar-filter-coffee', 'live', 'Kumar Filter Coffee Stand', 'Kumar', '👴🏽', 'Decoction first, conversation second.', 'Jayanagar', 12.925, 77.5838, '☕', 25, 'filter-coffee', array['Coffee', 'Snacks']::text[], true, 30, '6:00 AM – 9:00 PM', '{"taste":4.4,"hygiene":4.3,"value":4.9,"vibe":4}'::jsonb, 190, true, null, 2009, '[{"name":"Filter Coffee","price":20},{"name":"Mangalore Bajji","price":40}]'::jsonb, 'Strong, chicory-forward coffee at an unbeatable price. A neighbourhood institution.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('pema-momo-point', 'live', 'Momo Point by Pema', 'Pema', '👩🏻‍🍳', 'I make momos the way my mother did in Darjeeling.', 'Koramangala', 12.9352, 77.6245, '🥟', 200, 'momos', array['Momos', 'Evening']::text[], false, 100, '3:00 PM – 11:00 PM', '{"taste":4.8,"hygiene":4.5,"value":4.6,"vibe":4.9}'::jsonb, 302, true, (select id from public.profiles where handle = 'ananya'), 2021, '[{"name":"Chicken Steamed Momos","price":100},{"name":"Veg Fried Momos","price":90},{"name":"Thukpa","price":120}]'::jsonb, 'Juicy, thin-skinned momos with a fiery red chutney. Reviewers often mention it''s the closest to Darjeeling-style in the area.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('gowda-ragi-mudde', 'pending', 'Gowda''s Ragi Mudde Stall', 'Basavaraj Gowda', '👨🏽‍🌾', 'Food from my village, for your city.', 'HSR Layout', 12.9116, 77.6474, '🍲', 90, 'ragi-mudde', array['Meals', 'Lunch']::text[], false, 120, '12:00 PM – 3:30 PM', '{"taste":4.5,"hygiene":3.9,"value":4.6,"vibe":3.8}'::jsonb, 88, false, (select id from public.profiles where handle = 'karthik'), 2023, '[{"name":"Ragi Mudde + Saaru","price":90},{"name":"Naati Koli Saaru Meal","price":150}]'::jsonb, 'Home-style ragi mudde with a rich country-chicken curry. Small but growing fan base, and still collecting vouches.');
insert into public.stalls (id, status, name, vendor_name, vendor_avatar, vendor_quote, area, lat, lng, emoji, hue, dish, tags, veg, avg_price, timings, base_ratings, base_count, verified, suggested_by, since, dishes, ai_summary) values ('lakshmi-holige', 'live', 'Lakshmi Holige Stall', 'Lakshmi', '👵🏽', 'Every holige is rolled by hand, the old way.', 'Indiranagar', 12.9784, 77.6408, '🫓', 50, 'holige', array['Sweets', 'Snacks']::text[], true, 40, '10:00 AM – 8:00 PM', '{"taste":4.8,"hygiene":4.7,"value":4.6,"vibe":4.2}'::jsonb, 145, true, null, 2019, '[{"name":"Kayi Holige","price":35},{"name":"Bele Holige","price":35},{"name":"Holige + Ghee","price":50}]'::jsonb, 'Thin, generous holige with plenty of ghee. Many order in bulk for festivals.');
