insert into public.campaigns (id, stall_id, title, short_goal, story, goal, raised, backers, ends_on, cost_breakdown, revenue_share, milestones, insight, updates) values ('c-manju-second-tawa', 'manju-benne-dosa', 'A second tawa to halve the weekend queue', 'a second tawa', 'For 12 years I''ve made every dosa on one tawa. On weekends people wait 20 minutes, and some leave. A second tawa and a helper means twice the dosas and no one goes home hungry.', 60000, 48600, 87, current_date + 9, '[{"item":"Heavy cast-iron tawa + burner","amount":22000},{"item":"Extended steel counter","amount":18000},{"item":"Helper wages (2 months)","amount":20000}]'::jsonb, '{"pctOfGrowth":8,"cap":1.5,"baselineMonthly":210000}'::jsonb, '[{"title":"Fully funded","reward":"₹100 food credit","releasePct":40,"status":"in_progress"},{"title":"Second tawa live","reward":"₹200 credit + Tawa Backer badge","releasePct":40,"status":"locked"},{"title":"Revenue up 25%","reward":"₹300 credit + taste-score boost","releasePct":20,"status":"locked"}]'::jsonb, '{"summary":"A strong, low-risk case: demand clearly exceeds capacity. The upgrade directly targets the #1 complaint (queues).","signals":["Rating steady at 4.6+ for 18 months","\"Queue\" mentioned in 58% of recent reviews","Revenue reports consistent with UPI volume"],"risks":["Single location","Morning-only hours limit upside"]}'::jsonb, '[{"date":"2026-09-28","emoji":"🙏","text":"80% there! Thank you all. Got a quote for the tawa today."},{"date":"2026-09-20","emoji":"📸","text":"Measured the space for the extended counter. It fits!"}]'::jsonb);
insert into public.campaigns (id, stall_id, title, short_goal, story, goal, raised, backers, ends_on, cost_breakdown, revenue_share, milestones, insight, updates) values ('c-raju-clean-cart', 'raju-chaat-corner', 'Running water and a covered counter', 'running water and a covered counter', 'My chaat is loved, but people worry about hygiene. I want a cart with a water tank, a hand-wash tap and a covered glass counter so everyone can eat without a second thought.', 45000, 45000, 112, current_date + 0, '[{"item":"New cart with glass counter","amount":30000},{"item":"Water tank + tap fitting","amount":9000},{"item":"Steel serving ware","amount":6000}]'::jsonb, '{"pctOfGrowth":10,"cap":1.5,"baselineMonthly":165000}'::jsonb, '[{"title":"Fully funded","reward":"₹100 food credit","releasePct":50,"status":"done"},{"title":"New cart live","reward":"₹200 credit + Clean Cart badge","releasePct":30,"status":"in_progress"},{"title":"Hygiene rating ≥ 4.5","reward":"₹250 credit","releasePct":20,"status":"locked"}]'::jsonb, '{"summary":"Fixes the one weak spot of a top-rated stall. If the hygiene rating rises, more families and office crowds are likely to come.","signals":["Highest review volume in VV Puram","Taste 4.8, hygiene 3.6: a clear gap","Funded in 11 days"],"risks":["Food Street footfall is seasonal"]}'::jsonb, '[{"date":"2026-09-29","emoji":"🛒","text":"Cart is being built! Fabricator says 10 more days."},{"date":"2026-09-15","emoji":"🎉","text":"100% funded! I can''t believe it. Thank you, Bengaluru."}]'::jsonb);
insert into public.campaigns (id, stall_id, title, short_goal, story, goal, raised, backers, ends_on, cost_breakdown, revenue_share, milestones, insight, updates) values ('c-pema-food-truck', 'pema-momo-point', 'From cart to a small food truck', 'a food truck', 'Rain shuts my cart down for weeks every monsoon. A small second-hand food truck means I can cook in any weather and park near the tech parks at lunch.', 250000, 96000, 141, current_date + 24, '[{"item":"Second-hand mini truck","amount":160000},{"item":"Kitchen fit-out","amount":65000},{"item":"Permits + registration","amount":25000}]'::jsonb, '{"pctOfGrowth":12,"cap":1.6,"baselineMonthly":240000}'::jsonb, '[{"title":"Fully funded","reward":"₹150 food credit","releasePct":30,"status":"in_progress"},{"title":"Truck fitted & permitted","reward":"₹300 credit + Truck Crew badge","releasePct":50,"status":"locked"},{"title":"Lunch service at tech park","reward":"₹300 credit + Founding Backer plaque","releasePct":20,"status":"locked"}]'::jsonb, '{"summary":"Higher upside, higher risk. A truck unlocks monsoon months and a second daily service, but the goal is ambitious.","signals":["Rating rose 4.3 → 4.6 in a year","Fastest-growing stall in Koramangala","Suggested and vouched by top critics"],"risks":["Large goal: 38% funded with 24 days left","Permits can delay launch"]}'::jsonb, '[{"date":"2026-09-27","emoji":"🚚","text":"Found a truck in good condition. Mechanic check on Monday."}]'::jsonb);
insert into public.campaigns (id, stall_id, title, short_goal, story, goal, raised, backers, ends_on, cost_breakdown, revenue_share, milestones, insight, updates) values ('c-bhai-tandoor', 'shivajinagar-kebab-gaadi', 'A proper tandoor for naan and tikka', 'a proper tandoor', 'Customers keep asking for rotis with their kebabs. A tandoor lets me add naan and tandoori dishes and stay open on weekend afternoons too.', 80000, 31200, 46, current_date + 16, '[{"item":"Clay tandoor + insulation","amount":45000},{"item":"Exhaust hood","amount":20000},{"item":"Utensils + first stock","amount":15000}]'::jsonb, '{"pctOfGrowth":9,"cap":1.5,"baselineMonthly":320000}'::jsonb, '[{"title":"Fully funded","reward":"₹100 food credit","releasePct":40,"status":"in_progress"},{"title":"Tandoor installed","reward":"₹250 credit + Tandoor Club badge","releasePct":40,"status":"locked"},{"title":"Weekend afternoons open","reward":"₹200 credit","releasePct":20,"status":"locked"}]'::jsonb, '{"summary":"Adds a new menu category that customers keep asking for. Moderate risk, mostly around execution.","signals":["\"Roti\" or \"naan\" requested in 31% of reviews","Strong late-night demand"],"risks":["Space constraints on the street","Needs smoke management"]}'::jsonb, '[]'::jsonb);
insert into public.campaigns (id, stall_id, title, short_goal, story, goal, raised, backers, ends_on, cost_breakdown, revenue_share, milestones, insight, updates) values ('c-kumar-boiler', 'kumar-filter-coffee', 'A bigger decoction boiler for the evening rush', 'a bigger decoction boiler', 'Every evening the decoction ran out by 7 PM and people went home without coffee. A bigger brass boiler means fresh decoction till closing time.', 30000, 30000, 58, current_date + 0, '[{"item":"Brass decoction boiler","amount":18000},{"item":"Milk warmer + burner","amount":8000},{"item":"Steel tumblers & davaras","amount":4000}]'::jsonb, '{"pctOfGrowth":10,"cap":1.5,"baselineMonthly":120000}'::jsonb, '[{"title":"Fully funded","reward":"₹100 food credit","releasePct":50,"status":"done"},{"title":"New boiler running","reward":"₹100 credit + Decoction Backer badge","releasePct":30,"status":"done"},{"title":"Evening sales up 25%","reward":"₹100 credit","releasePct":20,"status":"done"}]'::jsonb, '{"summary":"Completed. Evening sales are up about 40% since the boiler arrived, and backers are being paid monthly.","signals":["All milestones verified","Revenue share paid 4 months in a row"],"risks":[]}'::jsonb, '[{"date":"2026-06-12","emoji":"☕","text":"New boiler running! Evening sales up 40% this month."},{"date":"2026-03-02","emoji":"🎉","text":"Funded in 6 days. Thank you!"}]'::jsonb);
